1→//! Private fixture probe. Never point this at a live identity.
use std::path::Path;

use anyhow::{Context, Result};
use op_network::seeded_root::{
    SeededRootDescriptor, ensure_seeded_root_mounted, verify_seeded_root_mounted,
};
use uuid::Uuid;

10→fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();
    anyhow::ensure!(
        args.len() == 9,
        "usage: ensure_seeded_root MODE SEED SHA SEED_FSID LEAF SPROUT_FSID MOUNT POOL"
    );
    let desc = SeededRootDescriptor {
        seed_image: Path::new(&args[2]),
        seed_sha256: &args[3],
        seed_fsid: Uuid::parse_str(&args[4]).context("seed FSID")?,
20→        leaf_image: Path::new(&args[5]),
        sprout_fsid: Uuid::parse_str(&args[6]).context("sprout FSID")?,
        mount_point: Path::new(&args[7]),
        pool_subvolume: &args[8],
    };
    let guard = match args[1].as_str() {
        "ensure" => ensure_seeded_root_mounted(&desc)?,
        "verify" => verify_seeded_root_mounted(&desc)?,
        _ => anyhow::bail!("mode must be ensure or verify"),
    };
30→    println!("mounted_now={}", guard.mounted_now);
    println!("seed_loop={}", guard.seed_loop.display());
    println!("leaf_loop={}", guard.leaf_loop.display());
    println!("pool_path={}", guard.pool_path.display());
    Ok(())
}

1→//! Handoff to the door over its local socket.
//!
//! Everything the transports terminate converges here and leaves over one
//! Unix socket. The door's interceptor is the only component that decides
//! whether a credential is good; this module delivers bytes and credential
//! unchanged, and fails closed when it cannot.
//!
//! The socket, not an address, is the boundary. An identity container never
//! binds an IP inside its own namespace: it receives the door socket as a
10→//! mount and reaches the control plane through it, so the kernel authenticates
//! the peer process and no fabric address has to exist for a local hop.

pub mod proxy;

pub use proxy::{DoorProxy, DoorTarget};

/// The door socket, at the path a container sees after it is mounted in.
///
/// Same path the bridge binds and the in-container 3tchedFS client consumes,
20→/// so host and guest name one socket rather than two conventions.
pub const DEFAULT_LUNGS_SOCKET: &str = "/run/opdbus/lungs/lungs.sock";

/// Bounded queue depth between a transport and the door.
///
/// When this fills, ingress sheds rather than buffering: a stalled door must
/// not translate into unbounded memory growth in this process.
pub const HANDOFF_QUEUE_DEPTH: usize = 1024;

1→//! Error types for the user-space ingress stack.
//!
//! One error enum spans transport termination, identity extraction and the
//! door handoff so a listener task can report any stage without boxing.

use std::io;

/// Failure from any stage of the user-space ingress path.
#[derive(Debug, thiserror::Error)]
10→pub enum NetworkError {
    /// The listener could not bind its configured socket.
    #[error("bind {addr} failed after {attempts} attempts: {source}")]
    Bind {
        addr: std::net::SocketAddr,
        attempts: u32,
        #[source]
        source: io::Error,
    },

20→    /// Transport-level framing, handshake or decryption failure.
    #[error("{transport} transport failure: {reason}")]
    Transport {
        transport: &'static str,
        reason: String,
    },

    /// The stream carried no identity credential, or an unusable one.
    ///
    /// Exactly one of SID1 or OIA1 must be present; both is a protocol error.
30→    #[error("identity rejected: {0}")]
    Identity(String),

    /// The door socket refused or dropped the connection.
    #[error("door handoff to {path} failed: {reason}")]
    Door {
        path: std::path::PathBuf,
        reason: String,
    },

40→    /// Downstream could not keep up and the bounded queue stayed full.
    ///
    /// Shedding here is deliberate: it bounds memory instead of letting the
    /// ingress buffer grow without limit.
    #[error("ingress backpressure: {0} dropped")]
    Backpressure(&'static str),

    #[error(transparent)]
    Io(#[from] io::Error),
}
50→
impl NetworkError {
    /// Build a transport failure without formatting at every call site.
    pub fn transport(transport: &'static str, reason: impl Into<String>) -> Self {
        Self::Transport {
            transport,
            reason: reason.into(),
        }
    }

60→    /// Whether the connection manager should try the next configured ingress.
    ///
    /// Transport and door faults are transient by nature. An identity
